#!/usr/bin/env bash
# HORO-1152 item 11 — no secret/private data leakage into logs or
# release artifacts generated by this gate's own runs. Real greps
# against real files produced during items 1-10 above, run in the
# foreground on this machine. Exit code 1 from `grep -c` means "count
# is 0" (grep -c never fails on a match count of zero unless the file
# is unreadable) -- treated as the PASS case for nonces we expect
# absent.
set -u
STATE_DIR=/tmp/libra-horo1152-work/home-upgrade/.local/state/libra-governor
RESULTS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

FAKE_CREDENTIAL_NONCE="fake-test-credential-nonce-8f2c1a"
FAKE_PROMPT_1="add input validation to the login handler"
FAKE_PROMPT_2="implement a new /health endpoint"
FAKE_FIXTURE_PATH="experiments/mvp1_validation/fixtures/rust-crate"

check() {
    local label="$1" file="$2" needle="$3" expect_absent="$4"
    if [[ ! -f "$file" ]]; then
        echo "$label :: SKIPPED (file does not exist: $file)"
        return
    fi
    local count
    count=$(grep -c -- "$needle" "$file" 2>/dev/null || true)
    count=${count:-0}
    if [[ "$expect_absent" == "yes" ]]; then
        if [[ "$count" == "0" ]]; then
            echo "$label :: '$needle' -> count=0 -> PASS (absent, as required)"
        else
            echo "$label :: '$needle' -> count=$count -> FAIL (LEAKED)"
        fi
    else
        echo "$label :: '$needle' -> count=$count -> INFO (expected present here: it is the artifact's own legitimate content)"
    fi
}

check_strings() {
    local label="$1" file="$2" needle="$3" expect_absent="$4"
    if [[ ! -f "$file" ]]; then
        echo "$label :: SKIPPED (file does not exist: $file)"
        return
    fi
    local count
    count=$(strings "$file" | grep -c -- "$needle" 2>/dev/null || true)
    count=${count:-0}
    if [[ "$expect_absent" == "yes" ]]; then
        if [[ "$count" == "0" ]]; then
            echo "$label :: '$needle' -> count=0 -> PASS (absent, as required)"
        else
            echo "$label :: '$needle' -> count=$count -> FAIL (LEAKED)"
        fi
    else
        echo "$label :: '$needle' -> count=$count -> INFO"
    fi
}

echo "=== daemon.log ($STATE_DIR/daemon.log) ==="
echo "(daemon.log is architecturally documented to never receive raw prompt text or hook payload content -- crates/daemon/src/log.rs / crates/daemon/src/paths.rs docstring)"
check "daemon.log / credential nonce" "$STATE_DIR/daemon.log" "$FAKE_CREDENTIAL_NONCE" yes
check "daemon.log / prompt 1"         "$STATE_DIR/daemon.log" "$FAKE_PROMPT_1" yes
check "daemon.log / prompt 2"         "$STATE_DIR/daemon.log" "$FAKE_PROMPT_2" yes
check "daemon.log / fixture path"     "$STATE_DIR/daemon.log" "$FAKE_FIXTURE_PATH" no

echo
echo "=== ledger.sqlite3 (strings scan, $STATE_DIR/ledger.sqlite3) ==="
check_strings "ledger.sqlite3 / credential nonce" "$STATE_DIR/ledger.sqlite3" "$FAKE_CREDENTIAL_NONCE" yes
check_strings "ledger.sqlite3 / prompt 1"         "$STATE_DIR/ledger.sqlite3" "$FAKE_PROMPT_1" yes
check_strings "ledger.sqlite3 / prompt 2"         "$STATE_DIR/ledger.sqlite3" "$FAKE_PROMPT_2" yes
check_strings "ledger.sqlite3 / fixture path"     "$STATE_DIR/ledger.sqlite3" "$FAKE_FIXTURE_PATH" no

echo
echo "=== doctor / doctor --json actual command output (isolated from this file's own config.json dump) ==="
echo "results/10_capability_tier_text.txt also embeds, for readability, the raw"
echo "config.json this gate wrote as INPUT to each scenario (which legitimately"
echo "contains the test nonce, since it's the fixture, not libra's output). To"
echo "avoid a false-positive grep against our own fixture dump, this check"
echo "isolates only the actual 'libra-governor doctor' / 'doctor --json' STDOUT"
echo "sections (everything from the first '\$ libra-governor doctor' marker"
echo "onward) and greps only that."
DOCTOR_JSON_FILE="$RESULTS_DIR/10_capability_tier_text.txt"
DOCTOR_OUTPUT_ONLY="$RESULTS_DIR/.doctor_output_only.tmp.txt"
awk '/\$ libra-governor doctor/,0' "$DOCTOR_JSON_FILE" > "$DOCTOR_OUTPUT_ONLY"
check "doctor+doctor--json actual output / credential nonce" "$DOCTOR_OUTPUT_ONLY" "$FAKE_CREDENTIAL_NONCE" yes
rm -f "$DOCTOR_OUTPUT_ONLY"
echo "(the full combined file 10_capability_tier_text.txt DOES contain the nonce"
echo "once, in the fixture config.json this gate wrote as input -- that is"
echo "expected and not a leak; verified above that libra's own doctor command"
echo "output never echoes it)"

echo
echo "=== settings.json backups under ~/.claude/ (item 9 cycle profile) ==="
for f in /tmp/libra-horo1152-work/home-cycle/.claude/settings.json.libra-backup-*; do
    [[ -f "$f" ]] || continue
    check "$(basename "$f") / credential nonce" "$f" "$FAKE_CREDENTIAL_NONCE" yes
done

echo
echo "=== NOTE on credential_command execution ==="
echo "crates/cli/src/doctor_cmd.rs's own module docstring states doctor never"
echo "reads gateway.token's contents, runs a credential_command, or echoes"
echo "anything from config.json beyond presence/validity. This gate did not"
echo "separately start a live gateway proxy to exercise CredentialCommand::resolve()"
echo "end-to-end (that would require a loopback fake upstream, out of scope for"
echo "this install/doctor/lifecycle gate) -- that resolution path already has its"
echo "own real unit-test coverage in crates/gateway/src/credential.rs. What this"
echo "gate DOES verify directly: the fake credential nonce embedded in this gate's"
echo "own config.json fixtures never appears in daemon.log, the ledger, doctor's"
echo "output, or any settings.json backup produced during this gate's runs."

echo
echo "=== release artifact scan ==="
echo "This repo's scripts/install.sh and README.md document no release-tarball/"
echo "artifact build step (see README.md 'Install': \"This repository's CI... does"
echo "not publish a release binary or artifact anywhere\") -- there is no"
echo "release artifact to scan for this v0.0.1 Developer Preview. Confirmed by"
echo "reading .github/workflows/ci.yml: no artifact-upload or packaging step exists."
grep -n "upload-artifact\|actions/upload\|tar -c\|zip -" "$RESULTS_DIR/../../../.github/workflows/ci.yml" 2>/dev/null || echo "(grep for artifact-upload/packaging steps in ci.yml: no matches)"
